"""mnist_cnn - generated by AI Made Easy."""
import keras
from keras import layers


def build_model() -> keras.Model:
    inputs = keras.Input(shape=(28, 28, 1,))
    x_conv2d_1 = layers.Conv2D(filters=16, kernel_size=3, strides=1, padding=(1, 1,), dilation_rate=1)(inputs)
    x_relu_1 = layers.ReLU()(x_conv2d_1)
    x_maxpool2d_1 = layers.MaxPooling2D(pool_size=2, strides=2, padding='valid')(x_relu_1)
    x_conv2d_2 = layers.Conv2D(filters=32, kernel_size=3, strides=1, padding=(1, 1,), dilation_rate=1)(x_maxpool2d_1)
    x_relu_2 = layers.ReLU()(x_conv2d_2)
    x_global_avgpool2d_1 = layers.GlobalAveragePooling2D()(x_relu_2)
    x_dense_1 = layers.Dense(units=10, use_bias=True)(x_global_avgpool2d_1)
    return keras.Model(inputs=inputs, outputs=x_dense_1)


if __name__ == "__main__":
    model = build_model()
    model.summary()
